def view(query=''):
 terms=set(str(query).lower().replace('-',' ').split());models=[{'id':k,**copy.deepcopy(v)} for k,v in MODELS.items()]
 if terms:models.sort(key=lambda r:-sum(t in json.dumps(r).lower() for t in terms))
 return {'domains':[{'id':k,'title':v[0],'terms':v[1],'source':v[2]} for k,v in DOMAINS.items()],'links':[{'from':a,'to':b} for a,b in LINKS],'action_models':models,'prayer_application':PRAYER,'four_way':['true good','false good','true evil','false evil','unresolved'],'scope':'Connected conditional reference and action models; documentation, simulations and observed system results are separate. No implicit remote access or host execution.'}

def model(name):
 if name not in MODELS:raise ValueError('Choose a registered systemic action model')
 return {'id':name,**copy.deepcopy(MODELS[name]),'prayer_application':PRAYER,'required_assessment':['affected parties','severity and duration','distribution of benefits and harms','action versus inaction','alternatives','authority','reversibility','evidence gaps'],'status':'conditional model; real-world outcome unverified'}
